const std::size_t kSt7789GlyphCount = sizeof(kSt7789Glyphs) / sizeof(kSt7789Glyphs[0]);

const St7789Glyph* findSt7789Glyph(std::uint32_t codepoint) {
    std::size_t low = 0;
    std::size_t high = kSt7789GlyphCount;
    while (low < high) {
        const std::size_t mid = low + (high - low) / 2;
        if (kSt7789Glyphs[mid].codepoint == codepoint) {
            return &kSt7789Glyphs[mid];
        }
        if (kSt7789Glyphs[mid].codepoint < codepoint) {
            low = mid + 1;
        } else {
            high = mid;
        }
    }
    return nullptr;
}

